import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# packet.ActorPickRequest{EntityUniqueID: 4294967298, HotBarSlot: 200, WithData: true}
WITH_DATA = bytes.fromhex("0200000001000000c801")

# generated by gophertunnel b8bd735:
# packet.ActorPickRequest{EntityUniqueID: -1, HotBarSlot: 0, WithData: false}
NEGATIVE_ID = bytes.fromhex("ffffffffffffffff0000")

GOLDENS = [
    pytest.param(
        v2225.ActorPickRequestPacket(id=4294967298, max_slots=200, with_data=True),
        WITH_DATA,
        id="with-data",
    ),
    pytest.param(v2225.ActorPickRequestPacket(id=-1), NEGATIVE_ID, id="negative-id"),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_actor_pick_request_is_packet_35(version):
    assert version.PACKETS[35] is version.ActorPickRequestPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_actor_pick_request_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_actor_pick_request_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
